CREATE TABLE IF NOT EXISTS facilities ( id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE, sort_order INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL );
CREATE TABLE IF NOT EXISTS kiosks ( id INTEGER PRIMARY KEY AUTOINCREMENT, token_hash TEXT NOT NULL UNIQUE, facility_id INTEGER NOT NULL REFERENCES facilities(id), name TEXT NOT NULL DEFAULT '', created_by INTEGER, created_at TEXT NOT NULL, last_seen_at TEXT, revoked INTEGER NOT NULL DEFAULT 0 );
CREATE INDEX IF NOT EXISTS idx_kiosks_facility ON kiosks(facility_id);
